import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";

const formatTimelineDate = (timestamp: bigint): string => {
  const date = new Date(Number(timestamp));
  const today = new Date();
  const yesterday = new Date(today);
  yesterday.setDate(yesterday.getDate() - 1);

  const dateOnly = new Date(
    date.getFullYear(),
    date.getMonth(),
    date.getDate(),
  );
  const todayOnly = new Date(
    today.getFullYear(),
    today.getMonth(),
    today.getDate(),
  );
  const yesterdayOnly = new Date(
    yesterday.getFullYear(),
    yesterday.getMonth(),
    yesterday.getDate(),
  );

  if (dateOnly.getTime() === todayOnly.getTime()) return "Today";

  if (dateOnly.getTime() === yesterdayOnly.getTime()) return "Yesterday";

  return date.toLocaleDateString("en-US", {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
  });
};

/** Helper function to group events by date and add dividers */
export const addDateDividers = (
  events: EventTimelineItem[],
): TimelineListItem[] => {
  const result: TimelineListItem[] = [];
  let lastDate: string | null = null;

  for (const event of events) {
    const eventDate = formatTimelineDate(event.timestamp);

    if (eventDate !== lastDate) {
      result.push({
        type: "divider",
        date: eventDate,
        id: `divider-${event.timestamp}`,
      });
      lastDate = eventDate;
    }

    result.push({ type: "event", data: event });
  }

  return result;
};

import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";
import {
  MessageType_Tags,
  MsgLikeKind_Tags,
  TimelineItemContent_Tags,
} from "@unomed/react-native-matrix-sdk";

const isInfoEvent = (event: EventTimelineItem): boolean => {
  const tag = event.content.tag;

  if (tag === TimelineItemContent_Tags.RoomMembership) return true;
  if (tag === TimelineItemContent_Tags.ProfileChange) return true;

  if (tag === TimelineItemContent_Tags.State) {
    const stateContent = event.content.inner.content;
    if (stateContent.tag.includes("Room")) return true;
  }

  if (tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Other) return true;
    }
  }

  return false;
};

export const groupInfoEvents = (
  items: TimelineListItem[],
): TimelineListItem[] => {
  const result: TimelineListItem[] = [];
  let currentGroup: EventTimelineItem[] = [];

  const flushGroup = () => {
    if (currentGroup.length === 0) return;
    if (currentGroup.length === 1) {
      result.push({ type: "event", data: currentGroup[0] });
    } else {
      result.push({
        type: "group",
        events: [...currentGroup],
        id: `group-${currentGroup[0].timestamp}`,
      });
    }
    currentGroup = [];
  };

  for (const item of items) {
    if (item.type === "divider") {
      flushGroup();
      result.push(item);
      continue;
    }

    if (item.type !== "event") {
      flushGroup();
      result.push(item);
      continue;
    }

    if (isInfoEvent(item.data)) {
      currentGroup.push(item.data);
    } else {
      flushGroup();
      result.push(item);
    }
  }

  flushGroup();
  return result;
};

